/**
 * Allergen box on the recipe page. Data lives in each recipe's "allergens" field
 * (generated by scripts/allergens.mjs, then reviewed by hand).
 */
const LABEL = {
  gluten: 'Gluten', milk: 'Milk', egg: 'Egg', peanuts: 'Peanuts', 'tree nuts': 'Tree nuts', sesame: 'Sesame',
  soy: 'Soy', fish: 'Fish', shellfish: 'Shellfish', mustard: 'Mustard', celery: 'Celery', sulphites: 'Sulphites',
  lupin: 'Lupin', molluscs: 'Molluscs',
};
const Chip = ({ children, faded }) => (
  <span
    className={`inline-block px-3 pt-[9px] pb-[7px] font-pixel text-[9px] leading-none ${faded ? 'bg-surface text-text' : 'bg-primary text-ink'}`}
    style={{ boxShadow: '0 0 0 3px var(--outline)' }}
  >
    {children}
  </span>
);

export default function AllergyInfo({ allergens }) {
  if (!allergens) return null;
  const { contains = [], optional = [], check = [], swaps = [] } = allergens;
  return (
    <section aria-labelledby="allergy-h" className="flex flex-col gap-4 rounded-[14px] bg-surface-2 p-5" style={{ boxShadow: '0 0 0 3px var(--outline)' }}>
      <h2 id="allergy-h" className="text-[12px] text-text">ALLERGENS</h2>

      <div className="flex flex-col gap-2">
        <p className="text-[20px] text-muted">Contains</p>
        {contains.length ? (
          <div className="flex flex-wrap gap-3 p-1">{contains.map((a) => <Chip key={a}>{LABEL[a] || a}</Chip>)}</div>
        ) : (
          <p className="text-[22px] text-text">None of the 14 major allergens, as written.</p>
        )}
      </div>

      {optional.length > 0 && (
        <div className="flex flex-col gap-2">
          <p className="text-[20px] text-muted">Only in optional or swappable ingredients</p>
          <div className="flex flex-wrap gap-3 p-1">{optional.map((a) => <Chip key={a} faded>{LABEL[a] || a}</Chip>)}</div>
        </div>
      )}

      {check.length > 0 && (
        <div className="flex flex-col gap-1">
          <p className="text-[20px] text-muted">Check the label</p>
          <ul className="flex flex-col gap-1 text-[21px] leading-[1.15] text-text">
            {check.map((c) => <li key={c}>▸ {c}</li>)}
          </ul>
        </div>
      )}

      {swaps.length > 0 && (
        <div className="flex flex-col gap-1">
          <p className="text-[20px] text-muted">Allergy-friendly swaps</p>
          <ul className="flex flex-col gap-1 text-[21px] leading-[1.15] text-text">
            {swaps.map((s) => <li key={s}>▸ {s}</li>)}
          </ul>
        </div>
      )}

      <p className="text-[18px] leading-tight text-muted">
        A guide to the 14 major allergens, based on the ingredients as listed. Brands differ, so always read the labels, and check
        with a doctor or dietitian if an allergy is severe.
      </p>
    </section>
  );
}
